#!/usr/bin/env node
// Bring `main` into `staging` on a staging-flow site, with pnpm-lock.yaml regenerated by
// pnpm instead of merged as text.
//
//   node scripts/staging-bring-main.mjs [--dir <site checkout>] [--main <ref>] [--staging <ref>]
//                                       [--branch <name>] [--no-fetch] [--pnpm "<command>"]
//
// Why (2026-11-03): on the staging flow, Renovate's patches and minors land on `main` and
// lock-file maintenance lands on `staging`, so both branches rewrite pnpm-lock.yaml between
// promotions. The weekly refresh moves transitive resolutions all over the file, and git then
// conflicts on the lockfile and nothing else: caltex-landing#104 against #105 (51 hunks) and
// medical-solutions-of-texas#111 against #113 left both the bring-main PR and the promotion
// PR dirty. The bring-main PR with head `main` cannot be resolved on GitHub, which merges
// lockfiles as text (it runs no merge driver). This script is the runbook's conflict path,
// done the same way every time:
//
//   1. fetch `main` and `staging` (unless --no-fetch); nothing to do when `main` is already an
//      ancestor of `staging`;
//   2. in a temporary worktree at `staging`, `git merge --no-ff --no-commit main`;
//   3. a conflict in any file but pnpm-lock.yaml stops with exit 2: that is a real fork (a
//      major on `staging` against a minor of the same package on `main`) and a human's;
//   4. `pnpm install --lockfile-only --ignore-scripts` with the site's pinned pnpm (its
//      `packageManager`, through corepack). pnpm resolves conflict markers in its own lockfile
//      ("Merge conflict detected in pnpm-lock.yaml and successfully merged") and re-resolves
//      anything the merged package.json no longer matches. It runs on a clean textual merge
//      too, because two clean hunks can still make a lockfile that disagrees with package.json;
//   5. refuse the result if any conflict marker or unmerged path is left;
//   6. commit it as a merge commit, so `main` is a parent and the promotion PR has nothing
//      left to merge from `main`, and create <branch> at it in the checkout.
//
// It changes nothing on GitHub: push <branch>, open its PR into `staging`, and merge that PR
// as a merge commit on green (docs/runbooks/staging-flow.md, "Promotion, each time").
//
// Exit codes: 0 the branch was made, or there was nothing to bring; 2 a conflict outside
// pnpm-lock.yaml (nothing was made); 1 any other failure (nothing was made).
import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { flagValue, isMain } from "./lib/cli.mjs";

export const LOCKFILE = "pnpm-lock.yaml";
const USAGE =
  "usage: node scripts/staging-bring-main.mjs [--dir <site checkout>] [--main <ref>] [--staging <ref>]\n" +
  '                                           [--branch <name>] [--no-fetch] [--pnpm "<command>"]\n' +
  "exit: 0 made or nothing to bring, 2 a conflict outside pnpm-lock.yaml, 1 error";

export function parseArgs(argv, now = new Date()) {
  const stamp = now.toISOString().slice(0, 16).replace(/[-:]/g, "").replace("T", "-");
  const o = {
    dir: process.cwd(),
    main: "origin/main",
    staging: "origin/staging",
    branch: `claude/main-into-staging-${stamp}`,
    fetch: true,
    pnpm: undefined,
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--dir") o.dir = resolve(flagValue(argv[++i], a));
    else if (a === "--main") o.main = flagValue(argv[++i], a);
    else if (a === "--staging") o.staging = flagValue(argv[++i], a);
    else if (a === "--branch") o.branch = flagValue(argv[++i], a);
    else if (a === "--pnpm") o.pnpm = flagValue(argv[++i], a);
    else if (a === "--no-fetch") o.fetch = false;
    else throw new Error(`unknown argument: ${a}\n${USAGE}`);
  }
  return o;
}

function git(cwd, args) {
  const r = spawnSync("git", args, { cwd, encoding: "utf8" });
  return { code: r.status ?? 1, stdout: (r.stdout ?? "").trim(), stderr: (r.stderr ?? "").trim() };
}

function mustGit(cwd, args) {
  const r = git(cwd, args);
  if (r.code !== 0) throw new Error(`git ${args.join(" ")} failed: ${r.stderr || r.stdout}`);
  return r.stdout;
}

/** The pnpm to run: --pnpm as given, else the site's pinned `packageManager` through corepack, else `pnpm`. */
export function pnpmCommand(siteDir, override) {
  if (override) return override.split(/\s+/).filter(Boolean);
  try {
    const pm = JSON.parse(readFileSync(join(siteDir, "package.json"), "utf8")).packageManager;
    const m = typeof pm === "string" && /^pnpm@([^+\s]+)/.exec(pm);
    if (m) return ["corepack", `pnpm@${m[1]}`];
  } catch {
    // no package.json, or not JSON: fall through to the pnpm on PATH
  }
  return ["pnpm"];
}

const MARKER = /^(<{7}|={7}|>{7})( |$)/m;

/**
 * @returns {{status: "up-to-date"} | {status: "conflict", files: string[]} |
 *           {status: "made", branch: string, sha: string, main: string, staging: string, lockfileConflicted: boolean}}
 */
export function bringMain(o) {
  if (o.fetch) mustGit(o.dir, ["fetch", "-q", "origin", "main", "staging"]);
  const main = mustGit(o.dir, ["rev-parse", "--verify", `${o.main}^{commit}`]);
  const staging = mustGit(o.dir, ["rev-parse", "--verify", `${o.staging}^{commit}`]);
  if (git(o.dir, ["merge-base", "--is-ancestor", main, staging]).code === 0)
    return { status: "up-to-date" };
  if (git(o.dir, ["rev-parse", "--verify", "-q", `refs/heads/${o.branch}`]).code === 0)
    throw new Error(`branch ${o.branch} already exists`);

  const wt = join(mkdtempSync(join(tmpdir(), "bring-main-")), "wt");
  mustGit(o.dir, ["worktree", "add", "-q", "--detach", wt, staging]);
  try {
    const merged = git(wt, ["merge", "--no-ff", "--no-commit", main]);
    const unmerged = () =>
      git(wt, ["diff", "--name-only", "--diff-filter=U"]).stdout.split("\n").filter(Boolean);
    const conflicted = unmerged();
    const others = conflicted.filter((f) => f !== LOCKFILE);
    if (others.length) {
      git(wt, ["merge", "--abort"]);
      return { status: "conflict", files: others };
    }
    if (merged.code !== 0 && conflicted.length === 0)
      throw new Error(`git merge failed: ${merged.stderr || merged.stdout}`);

    if (existsSync(join(wt, LOCKFILE))) {
      const [cmd, ...pre] = pnpmCommand(wt, o.pnpm);
      const env = { ...process.env, COREPACK_ENABLE_DOWNLOAD_PROMPT: "0" };
      const r = spawnSync(
        cmd,
        [...pre, "install", "--lockfile-only", "--ignore-scripts", "--no-frozen-lockfile"],
        {
          cwd: wt,
          env,
          encoding: "utf8",
        },
      );
      if (r.status !== 0)
        throw new Error(`${cmd} ${pre.join(" ")} install failed:\n${r.stderr || r.stdout}`);
      if (MARKER.test(readFileSync(join(wt, LOCKFILE), "utf8")))
        throw new Error(
          `${LOCKFILE} still has conflict markers after ${[cmd, ...pre].join(" ")} install`,
        );
      mustGit(wt, ["add", LOCKFILE]);
    }
    const left = unmerged();
    if (left.length) throw new Error(`still unmerged: ${left.join(", ")}`);

    const how = conflicted.includes(LOCKFILE)
      ? `${LOCKFILE} conflicted and was regenerated by \`pnpm install --lockfile-only\`, not merged by hand.`
      : `${LOCKFILE} merged as text and was checked by \`pnpm install --lockfile-only\`.`;
    mustGit(wt, [
      "commit",
      "-q",
      "--no-verify",
      "-m",
      "Merge main into staging",
      "-m",
      `main ${main.slice(0, 7)} into staging ${staging.slice(0, 7)}, by scripts/staging-bring-main.mjs ` +
        `(reddoorla/reddoor-maintenance). ${how}`,
    ]);
    const sha = mustGit(wt, ["rev-parse", "HEAD"]);
    mustGit(o.dir, ["branch", o.branch, sha]);
    return {
      status: "made",
      branch: o.branch,
      sha,
      main,
      staging,
      lockfileConflicted: conflicted.includes(LOCKFILE),
    };
  } finally {
    git(o.dir, ["worktree", "remove", "--force", wt]);
  }
}

if (isMain(import.meta.url)) {
  let code = 1;
  try {
    const r = bringMain(parseArgs(process.argv.slice(2)));
    if (r.status === "up-to-date") {
      console.log("nothing to bring: main is already an ancestor of staging");
      code = 0;
    } else if (r.status === "conflict") {
      console.error(
        `stopped: main and staging conflict outside ${LOCKFILE}, in ${r.files.join(", ")}. ` +
          "That is a real fork, not the lockfile race; nothing was made.",
      );
      code = 2;
    } else {
      console.log(
        `made ${r.branch} at ${r.sha.slice(0, 7)}: main ${r.main.slice(0, 7)} into staging ${r.staging.slice(0, 7)}` +
          (r.lockfileConflicted
            ? `, ${LOCKFILE} regenerated`
            : `, ${LOCKFILE} merged cleanly and checked`),
      );
      console.log(
        `next: git push origin ${r.branch}; open its PR into staging; merge it on green as a merge commit, never a squash`,
      );
      code = 0;
    }
  } catch (e) {
    console.error(`staging-bring-main: ${e instanceof Error ? e.message : String(e)}`);
  }
  process.exitCode = code;
}
